package cn.kaoyan.assistant;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import java.io.*;
public class AttachmentProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 private File file(Uri u) throws FileNotFoundException {String n=u.getLastPathSegment();if(n==null||!n.matches("[a-zA-Z0-9._-]{1,100}"))throw new FileNotFoundException();File f=new File(new File(getContext().getFilesDir(),"attachments"),n);if(!f.isFile())throw new FileNotFoundException();return f;}
 static String typeFor(String n){if(n.endsWith(".jpg")||n.endsWith(".jpeg"))return "image/jpeg";if(n.endsWith(".png"))return "image/png";if(n.endsWith(".webp"))return "image/webp";if(n.endsWith(".heic"))return "image/heic";if(n.endsWith(".pdf"))return "application/pdf";if(n.endsWith(".pptx"))return "application/vnd.openxmlformats-officedocument.presentationml.presentation";if(n.endsWith(".ppt"))return "application/vnd.ms-powerpoint";if(n.endsWith(".doc"))return "application/msword";if(n.endsWith(".docx"))return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";return "text/plain";}
 public String getType(Uri u){return typeFor(u.getLastPathSegment()==null?"":u.getLastPathSegment());}
 public ParcelFileDescriptor openFile(Uri u,String mode) throws FileNotFoundException {if("r".equals(mode))return ParcelFileDescriptor.open(file(u),ParcelFileDescriptor.MODE_READ_ONLY);if("w".equals(mode)||"wt".equals(mode)||"rw".equals(mode)||"rwt".equals(mode))return ParcelFileDescriptor.open(file(u),ParcelFileDescriptor.MODE_READ_WRITE|ParcelFileDescriptor.MODE_TRUNCATE);throw new FileNotFoundException();}
 public Cursor query(Uri u,String[] p,String s,String[] a,String sort){try{File f=file(u);MatrixCursor c=new MatrixCursor(new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE});c.addRow(new Object[]{f.getName(),f.length()});return c;}catch(Exception e){return null;}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
